import { createContext, useContext, useState, useEffect } from "react";
import { AuthContext } from "./AuthContext";

export const UserContext = createContext();

export const UserProvider = ({ children }) => {
  const { token } = useContext(AuthContext);
  const [userData, setUserData] = useState(null);
  const [loading, setLoading] = useState(true);

  // Format date → YYYY-MM-DD
  const formatDate = (d) => d.toISOString().split("T")[0];

  // Période par défaut : mois courant
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);

  const [period, setPeriod] = useState({
    startDate: formatDate(start),
    endDate: formatDate(end),
  });

  useEffect(() => {
    if (!token) {
      setUserData(null);
      setLoading(false);
      return;
    }

    const fetchUserData = async () => {
      try {
        setLoading(true);

        // 1) Profil + stats
        const infoRes = await fetch("http://localhost:8000/api/user-info", {
          headers: { Authorization: `Bearer ${token}` },
        });
        const info = await infoRes.json();

        // 2) Sessions filtrées
        const activityRes = await fetch(
          `http://localhost:8000/api/user-activity?startWeek=${period.startDate}&endWeek=${period.endDate}`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        const sessions = await activityRes.json();

        setUserData({
          profile: info.profile,
          statistics: info.statistics,
          sessions,
          startDate: period.startDate,
          endDate: period.endDate,
        });
      } catch (err) {
        console.error("Erreur UserContext :", err);
      } finally {
        setLoading(false);
      }
    };

    fetchUserData();
  }, [token, period]);

  return (
    <UserContext.Provider value={{ userData, loading, setPeriod }}>
      {children}
    </UserContext.Provider>
  );
};

export const useUser = () => useContext(UserContext);
